 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color as colorNode } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new THREE.Group();
  group.name = config.id ?? 'quote-panel-pricing';

  const baseScale = Array.isArray(config.sceneScale)
    ? new THREE.Vector3(config.sceneScale[0], config.sceneScale[1], config.sceneScale[2])
    : new THREE.Vector3(1, 1, 1);
  group.scale.copy(baseScale);

  const baseY = config.scenePosition?.[1] ?? 0;

  const cardW = 3.2;
  const cardH = 2.0;

  const backGeom = new THREE.PlaneGeometry(cardW + 0.4, cardH + 0.4);
  const backMat = new MeshBasicNodeMaterial({
    colorNode: mix(colorNode(colors.ink), colorNode(colors.surface), uv().y),
    side: THREE.DoubleSide,
  });
  const backdrop = new THREE.Mesh(backGeom, backMat);
  backdrop.name = 'quote-panel-backdrop';
  backdrop.position.z = -0.08;
  group.add(backdrop);

  const edgeGeom = new THREE.PlaneGeometry(cardW + 0.12, cardH + 0.12);
  const edgeMat = new MeshBasicNodeMaterial({
    color: new THREE.Color(colors.accent),
    transparent: true,
    opacity: 0.15,
    side: THREE.DoubleSide,
  });
  const edge = new THREE.Mesh(edgeGeom, edgeMat);
  edge.name = 'quote-panel-accent-edge';
  edge.position.z = -0.04;
  group.add(edge);

  const geom = new THREE.PlaneGeometry(cardW, cardH);
  const mat = new MeshBasicNodeMaterial({
    color: new THREE.Color(colors.paper),
    side: THREE.DoubleSide,
  });
  const card = new THREE.Mesh(geom, mat);
  card.name = 'quote-plane';
  card.position.z = 0.001;
  group.add(card);

  let loadedTexture = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      loadedTexture = tex;
      mat.map = tex;
      mat.needsUpdate = true;
    });
  }

  let hoverTL = null;
  let pressTL = null;

  function clearHover() {
    if (hoverTL) {
      hoverTL.kill();
      hoverTL = null;
    }
  }

  function clearPress() {
    if (pressTL) {
      pressTL.kill();
      pressTL = null;
    }
  }

  function onPointerOver() {
    clearHover();
    hoverTL = gsap.timeline({ overwrite: true });
    hoverTL.to(group.position, { y: baseY + 0.15, duration: 0.25, ease: 'power2.out' }, 0);
    hoverTL.to(edgeMat, { opacity: 0.9, duration: 0.2, ease: 'power2.out' }, 0);
  }

  function onPointerOut() {
    clearHover();
    hoverTL = gsap.timeline({ overwrite: true });
    hoverTL.to(group.position, { y: baseY, duration: 0.3, ease: 'power2.out' }, 0);
    hoverTL.to(edgeMat, { opacity: 0.15, duration: 0.2, ease: 'power2.out' }, 0);
  }

  function onPointerDown() {
    clearPress();
    pressTL = gsap.timeline({ overwrite: true });
    pressTL.to(group.scale, {
      x: baseScale.x * 0.97,
      y: baseScale.y * 0.97,
      z: baseScale.z * 0.97,
      duration: 0.12,
      ease: 'back.out(1.4)',
    });
  }

  function onPointerUp() {
    clearPress();
    pressTL = gsap.timeline({ overwrite: true });
    pressTL.to(group.scale, {
      x: baseScale.x,
      y: baseScale.y,
      z: baseScale.z,
      duration: 0.25,
      ease: 'power2.out',
    });
  }

  function onClick() {
    ctx.emit('hub-pricing.select', { nodeId: config.id, type: config.type });
  }

  const parallaxRef = ctx.primitives['parallax-scroll'](group, { intensity: 0.25 });

  group.userData = {
    handlers: {
      onPointerOver,
      onPointerOut,
      onPointerDown,
      onPointerUp,
      onClick,
    },
    cleanup: () => {
      clearHover();
      clearPress();
      if (parallaxRef?.cleanup) parallaxRef.cleanup();

      group.traverse((obj) => {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => {
              if (m.map) m.map.dispose();
              m.dispose();
            });
          } else {
            if (obj.material.map) obj.material.map.dispose();
            obj.material.dispose();
          }
        }
      });

      if (loadedTexture) loadedTexture.dispose();
    },
  };

  return group;
}
